          explanation: "It. Park ka zikr ho chuka hai, dusri dafa it ayega.",
        ),
        LessonMcq(
          question: "___ there a post office near your house?",
          options: <String>["Are", "Is", "Were are", "Have"],
          correctIndex: 1,
          explanation: "Is. Post office aik hai.",
        ),
        LessonMcq(
          question: "There ___ three men waiting at the gate.",
          options: <String>["is", "was is", "has", "are"],
